// Pick a valid TLS version code and request a printable name
unsigned int versions[4] = { 0x0301u, 0x0302u, 0x0303u, 0x0304u };
unsigned int tls_version = versions[*FUZZ_PARAM(unsigned int) % 4u];
char *name = getPrintableTLSName(tls_version);
// Treat returned pointer as read-only; do not free
(void)name;

// Allocate a new bs using default size. Ensure output param is NULL before call.
struct _bs *b = NULL;
bs_new(&b);
if (!b) { FUZZ_BAIL(); }
// Mark as a valid, initialized bs for downstream stubs
FUZZ_SET_ATTR_INT(b, "valid", 1);
// Provide b as an output so the runtime can manage its lifetime

// Ensure input is a valid initialized bs
if (FUZZ_GET_ATTR_INT(b, "valid") != 1) { FUZZ_BAIL(); }
// Free the bs and drop it from the pool by not returning it
struct _bs *tmp = b;
bs_free(&tmp);
// After bs_free, *parameter is set to NULL by the API; tmp is local and discarded

// Validate destination bs
if (FUZZ_GET_ATTR_INT(b, "valid") != 1) { FUZZ_BAIL(); }
// Generate a random data blob (cap size for performance)
std::string blob = FUZZ_PARAM_STR();
size_t n = blob.size();
if (n > 1024) { n = 1024; }
// If size > 0, source pointer must be non-NULL; std::string guarantees data() is non-null for n>0
bs_append_bytes(b, (unsigned char*)blob.data(), n);
// b may have reallocated internally; we continue to return the same bs handle

// Validate input bs
if (FUZZ_GET_ATTR_INT(b, "valid") != 1) { FUZZ_BAIL(); }
volatile size_t len = bs_get_len(b);
(void)len; // Consume result to prevent optimization

// Validate input and choose an in-bounds offset
if (FUZZ_GET_ATTR_INT(b, "valid") != 1) { FUZZ_BAIL(); }
size_t len = bs_get_len(b);
if (len == 0) { FUZZ_BAIL(); }
size_t off = (size_t)(*FUZZ_PARAM(unsigned int)) % len;
volatile unsigned char v = bs_get_byte(b, off);
(void)v;
